function ownedRun() {
  const file=fs.realpathSync(process.env.BOOT02_RUN_FILE||''); const dir=path.dirname(file);const stat=fs.statSync(file);
  if(path.dirname(dir)!==fs.realpathSync(os.tmpdir())||!path.basename(dir).startsWith('growdesk-integration-')||stat.uid!==process.getuid?.()||(stat.mode&0o077)) throw new Error('Use the owned integration runner');
  const run=JSON.parse(fs.readFileSync(file,'utf8')) as {directory:string;database:string;user:string;password:string;pgPort:number};
  if(run.directory!==dir||!run.user.startsWith('test_')||!run.database.startsWith('test_'))throw new Error('Unsafe test identity');
  return run;
}
test('Web background: durable jobs, ownership, cancellation, results and restart',async t=>{
  const run=ownedRun();
  const url=requireTestDatabaseUrl(`postgresql://${run.user}:${run.password}@127.0.0.1:${run.pgPort}/${run.database}?sslmode=disable`,{host:'127.0.0.1',port:run.pgPort,database:run.database,role:run.user,password:run.password});
  const ctx=createDatabaseContext({url});const pool=ctx.pool;
  const app=buildApiApp({databaseContext:ctx,jwtSecret:'test_web_background_at_least_32_characters'});
  const users:string[]=[];const families:string[]=[];const tasks:string[]=[];
  t.after(async()=>{try{await pool.query('DELETE FROM task_executions WHERE id=ANY($1)',[tasks]);await ctx.prisma.family.deleteMany({where:{id:{in:families}}});await ctx.prisma.user.deleteMany({where:{id:{in:users},username:{startsWith:'test_bg_'}}});}finally{await app.close();await ctx.close();}});
  async function tenant() {
    const response=await app.inject({method:'POST',url:'/api/v1/auth/register',payload:{username:`test_bg_${randomUUID()}`,password:'TestBackground123!',displayName:'test_background'}});
    assert.equal(response.statusCode,201,response.payload);const data=response.json<{data:{user:{id:string};accessToken:string}}>().data;
    users.push(data.user.id);const headers={authorization:`Bearer ${data.accessToken}`};
    const f=await app.inject({method:'GET',url:'/api/v1/families',headers});assert.equal(f.statusCode,200,f.payload);const familyId=f.json<{data:Array<{id:string}>}>().data[0]!.id;families.push(familyId);
    const b=await app.inject({method:'POST',url:`/api/v1/families/${familyId}/babies`,headers,payload:{name:'test_background_baby',gender:'other',birthDate:'2026-01-01'}});assert.equal(b.statusCode,201,b.payload);
    return {userId:data.user.id,familyId,babyId:b.json<{data:{id:string}}>().data.id,headers};
  }
  const a=await tenant(),b=await tenant();
  const env:NodeJS.ProcessEnv={NODE_ENV:'test',GROWDESK_AI_PROVIDER:'fixture',GROWDESK_AI_FIXTURE_TEXT:JSON.stringify({headline:'test_summary',sections:{feeding:'test',sleep:'test',diaper:'test',growthAndCare:'test',tomorrowTips:'test'}}),GROWDESK_AUDIO_FIXTURE_TEXT:'test_transcribed',S3_BUCKET:'test_media'};
  const service=new WebBackgroundService(pool,env);
  const create=async()=>{const job=await service.create(a.userId,{type:'daily_summary_synthesis',babyId:a.babyId,targetDate:'2026-09-15',clientRequestId:randomUUID()});tasks.push(job.id);return job;};
  await t.test('anonymous HTTP and cross-tenant jobs fail before enqueue',async()=>{
    assert.equal((await app.inject({method:'GET',url:'/api/v1/web/ai/jobs'})).statusCode,401);
    await assert.rejects(service.create(b.userId,{type:'daily_summary_synthesis',babyId:a.babyId,targetDate:'2026-09-15',clientRequestId:randomUUID()}),{code:'BABY_NOT_FOUND'});
    await assert.rejects(new WebBackgroundService(pool,{}).create(a.userId,{type:'daily_summary_synthesis',babyId:a.babyId,targetDate:'2026-09-15',clientRequestId:randomUUID()}),{code:'AI_NOT_CONFIGURED'});
  });
  await t.test('concurrent duplicate creation enqueues once; changed input conflicts',async()=>{
    const input={type:'daily_summary_synthesis' as const,babyId:a.babyId,targetDate:'2026-09-15',clientRequestId:randomUUID()};
    const jobs=await Promise.all([service.create(a.userId,input),service.create(a.userId,input)]);tasks.push(jobs[0]!.id);
    assert.equal(jobs[0]!.id,jobs[1]!.id);assert.equal((await pool.query('SELECT id FROM task_outbox WHERE aggregate_id=$1',[jobs[0]!.id])).rowCount,1);
    await assert.rejects(service.create(a.userId,{...input,targetDate:'2026-09-14'}),{code:'IDEMPOTENCY_KEY_REUSED'});
  });
  await t.test('summary result, task success and notification survive fresh service instances',async()=>{
    const job=await create();const worker=new WorkerEngine({pool,workerId:'test_bg_worker'});worker.registerProcessor(createMediaProcessor('daily_summary_synthesis',pool,{env}));
    const outcome=await worker.processTask(job.id,{userId:b.userId,babyId:b.babyId});assert.equal(outcome.status,'succeeded',outcome.error);
    const restored=await new WebBackgroundService(pool,env).get(a.userId,job.id);assert.equal(restored.status,'succeeded');assert.match(restored.resultJson!,/test_summary/);
    assert.equal((await pool.query('SELECT id FROM notifications WHERE id=$1 AND user_id=$2',[job.id,a.userId])).rowCount,1);
    assert.equal((await pool.query('SELECT id FROM daily_summaries WHERE baby_id=$1',[a.babyId])).rowCount,1);
    assert.equal((await service.act(a.userId,job.id,'claim')).claimed,true);
    await assert.rejects(service.get(b.userId,job.id),{code:'JOB_NOT_FOUND'});
  });
  await t.test('cancellation fences late publication; explicit retry is idempotent',async()=>{
    const job=await create();const claim=await TaskExecutionRepository.claimTask(pool,job.id,'test_cancel_worker',60);assert.ok(claim);
    await service.act(a.userId,job.id,'cancel');let published=false;
    await assert.rejects(publishTaskResult(pool,job.id,'test_cancel_worker',claim.fenceToken,{wrong:true},async()=>{published=true;}));assert.equal(published,false);
    const commandId=randomUUID();await service.act(a.userId,job.id,'retry',commandId);await service.act(a.userId,job.id,'retry',commandId);
    assert.equal((await pool.query('SELECT id FROM task_outbox WHERE aggregate_id=$1',[job.id])).rowCount,2);
    const next=await TaskExecutionRepository.claimTask(pool,job.id,'test_retry_worker',60);assert.equal(next!.attempt,2);
  });
  await t.test('revoked membership stops results and prevents job visibility',async()=>{
    const job=await create();await pool.query("UPDATE baby_members SET status='revoked' WHERE user_id=$1 AND baby_id=$2",[a.userId,a.babyId]);
    try {await assert.rejects(service.get(a.userId,job.id),{code:'JOB_NOT_FOUND'});const worker=new WorkerEngine({pool});worker.registerProcessor(createMediaProcessor('daily_summary_synthesis',pool,{env}));assert.equal((await worker.processTask(job.id)).status,'failed');}
    finally {await pool.query("UPDATE baby_members SET status='active' WHERE user_id=$1 AND baby_id=$2",[a.userId,a.babyId]);}
  });
  await t.test('expired worker cannot renew or publish and no paid automatic reclaim occurs',async()=>{
    const job=await create();const claim=await TaskExecutionRepository.claimTask(pool,job.id,'test_expired',60);assert.ok(claim);
    await pool.query("UPDATE task_executions SET lease_expires_at=CURRENT_TIMESTAMP-interval '1 second' WHERE id=$1",[job.id]);
    await assert.rejects(TaskExecutionRepository.heartbeat(pool,job.id,'test_expired',claim.fenceToken,60));
    assert.equal(await TaskExecutionRepository.claimTask(pool,job.id,'test_other',60),null);
    await TaskExecutionRepository.reconcile(pool);assert.equal((await service.get(a.userId,job.id)).status,'failed');
  });
  await t.test('audio uses verified private bytes, not a queue-controlled URL or identity',async()=>{
    const bytes=Buffer.from('test_audio_bytes');const id=randomUUID();
    await ctx.prisma.attachment.create({data:{id,familyId:a.familyId,babyId:a.babyId,uploaderId:a.userId,purpose:'voice_note',mimeType:'audio/wav',byteSize:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),objectKey:'test_private/audio',status:'ready',expiresAt:new Date(Date.now()+3600000)}});
    const job=await service.create(a.userId,{type:'voice_transcription',babyId:a.babyId,attachmentId:id,clientRequestId:randomUUID()});tasks.push(job.id);
    const worker=new WorkerEngine({pool});worker.registerProcessor(createMediaProcessor('voice_transcription',pool,{env,readMedia:async attachment=>{assert.equal(attachment.id,id);return bytes;}}));
    assert.equal((await worker.processTask(job.id,{attachmentId:randomUUID(),userId:b.userId})).status,'succeeded');assert.match((await service.get(a.userId,job.id)).resultJson!,/test_transcribed/);
  });
  await t.test('voice logs persist, isolate and acknowledge; notification dismissal is authoritative',async()=>{
    const input={id:randomUUID(),babyId:a.babyId,prompt:'test_prompt',reply:'test_reply',isAsync:true,isFastPath:false};
    await service.createVoiceLog(a.userId,input);await service.createVoiceLog(a.userId,input);
    assert.equal((await new WebBackgroundService(pool).listVoiceLogs(a.userId,{})).unreadLog!.id,input.id);
    assert.equal((await service.listVoiceLogs(b.userId,{})).logs.length,0);
    await service.acknowledgeVoiceLog(a.userId,input.id);assert.equal((await service.listVoiceLogs(a.userId,{})).unreadLog,null);
    await assert.rejects(service.acknowledgeVoiceLog(b.userId,input.id),{code:'VOICE_LOG_NOT_FOUND'});
    const rows=await pool.query<{id:string}>('SELECT id FROM notifications WHERE user_id=$1',[a.userId]);const notification=rows.rows[0]!.id;
    await assert.rejects(service.deleteNotification(b.userId,notification),{code:'NOTIFICATION_NOT_FOUND'});await service.deleteNotification(a.userId,notification);
  });
  await t.test('explicit history import is owned, idempotent and full-field recoverable',async()=>{
    const history=new WebHistoryService(pool);
    const source={id:'test_old_session',userId:a.userId,babyId:a.babyId,title:'test_history_title',contextType:'general',createdAt:'2026-09-10T12:00:00.000Z',updatedAt:'2026-09-10T12:00:01.000Z',extraLegacyMetadata:{preserved:true},messages:[{id:'test_old_message',sessionId:'test_old_session',role:'user',content:'test_history_content',createdAt:'2026-09-10T12:00:01.000Z'}]};
    await assert.rejects(history.importRecord(b.userId,'sessions',source),{code:'HISTORY_OWNER_MISMATCH'});
    const first=await history.importRecord(a.userId,'sessions',source);
    assert.equal((await history.importRecord(a.userId,'sessions',source)).alreadyImported,true);
    await assert.rejects(history.importRecord(a.userId,'sessions',{...source,title:'test_changed'}),{code:'HISTORY_SNAPSHOT_CHANGED'});
    assert.deepEqual((await history.exportRecord(a.userId,'sessions',source.id)).record,source);
    const session=await new WebAiSessionService(pool).get(a.userId,first.targetId);
    assert.equal(session.messages[0]!.content,'test_history_content');assert.equal(session.createdAt,source.createdAt);
    await new WebAiSessionService(pool).remove(a.userId,first.targetId);
    assert.equal((await history.importRecord(a.userId,'sessions',source)).alreadyImported,true);
    await assert.rejects(new WebAiSessionService(pool).get(a.userId,first.targetId),{code:'SESSION_NOT_FOUND'});
  });
  await t.test('invalid imported messages roll back the parent and immutable receipt',async()=>{
    const history=new WebHistoryService(pool);
    const source={id:'test_bad_session',userId:a.userId,babyId:a.babyId,title:'test_title',createdAt:'2026-09-10T12:00:00.000Z',messages:[{id:'test_bad_message',sessionId:'wrong',role:'user',content:'test',createdAt:'2026-09-10T12:00:00Z'}]};
    await assert.rejects(history.importRecord(a.userId,'sessions',source),{code:'INVALID_HISTORY'});
    await assert.rejects(history.exportRecord(a.userId,'sessions',source.id),{code:'HISTORY_NOT_FOUND'});
    assert.equal((await pool.query('SELECT id FROM ai_sessions WHERE user_id=$1 AND title=$2',[a.userId,'test_title'])).rowCount,0);
  });
  await t.test('archived unfinished jobs remain visible but are never automatically re-executed',async()=>{
    const history=new WebHistoryService(pool);
    const result=await history.importRecord(a.userId,'jobs',{id:'test_old_job',userId:a.userId,babyId:a.babyId,type:'medical_ocr',status:'processing',createdAt:'2026-09-10T12:00:00Z',imageUrl:'/uploads/test_history.png'});tasks.push(result.targetId);
    assert.equal((await service.get(a.userId,result.targetId)).status,'failed');
    assert.equal((await pool.query('SELECT id FROM task_outbox WHERE aggregate_id=$1',[result.targetId])).rowCount,0);
    await assert.rejects(service.act(a.userId,result.targetId,'retry',randomUUID()),{code:'LEGACY_JOB_REQUIRES_RESUBMISSION'});
  });
  await t.test('history HTTP endpoints reject unauthenticated and cross-owner imports',async()=>{
    const record={id:'test_http_log',userId:a.userId,babyId:a.babyId,prompt:'test_import',reply:'test_import_reply',isAsync:false,isFastPath:true,createdAt:'2026-09-10T12:00:00Z'};
    assert.equal((await app.inject({method:'POST',url:'/api/v1/web/history/import',payload:{kind:'voiceLogs',record}})).statusCode,401);
    assert.equal((await app.inject({method:'POST',url:'/api/v1/web/history/import',headers:b.headers,payload:{kind:'voiceLogs',record}})).statusCode,403);
    const response=await app.inject({method:'POST',url:'/api/v1/web/history/import',headers:a.headers,payload:{kind:'voiceLogs',record}});
    assert.equal(response.statusCode,200,response.payload);
    const verification=await app.inject({method:'GET',url:'/api/v1/web/history/export?kind=voiceLogs&sourceId=test_http_log',headers:a.headers});
    assert.equal(verification.statusCode,200,verification.payload);assert.deepEqual(verification.json<{data:{record:unknown}}>().data.record,record);
  });

  await t.test('read-only baby membership cannot generate a shared daily summary',async()=>{
    await pool.query("UPDATE baby_members SET role='viewer' WHERE user_id=$1 AND baby_id=$2",[a.userId,a.babyId]);
    try{await assert.rejects(create(),{code:'BABY_WRITE_DENIED'});}
    finally{await pool.query("UPDATE baby_members SET role='admin' WHERE user_id=$1 AND baby_id=$2",[a.userId,a.babyId]);}
  });

